def pick_lang(locale: str | None) -> str:
    l = (locale or "en").replace("_", "-")
    if l in LANGS:
        return l
    if l.lower().startswith(("nb", "no", "nn")):
        return "nb"
    if l.lower().startswith("pt"):
        return "pt-BR"
    base = l.split("-")[0].lower()
    return base if base in LANGS else "en"


def tr(locale: str | None, key: str, **kw) -> str:
    entry = STRINGS.get(key, {})
    text = entry.get(pick_lang(locale)) or entry.get("en") or key
    return text.format(**kw) if kw else text
